// Lot en entree : {ndjson:"ligne\nligne"} ou {prospects:[...]}. 60 prospects max par appel.
const inp = $input.first().json;
const body = inp.body || inp;
let rows = [];
if (Array.isArray(body.prospects)) rows = body.prospects;
else if (typeof body.ndjson === 'string') rows = body.ndjson.split('\n').map(l => l.trim()).filter(Boolean).map(l => JSON.parse(l));
const MAX = 60;
const STOP = new Set(['le','la','les','de','du','des','sarl','sas','eurl','sasu','et','chez','sci','ei']);
const slug = s => (s || '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const accent = t => t.replace(/[aeiouc]/g, c => ({a:'[aàâä]',e:'[eéèêë]',i:'[iîï]',o:'[oôö]',u:'[uùûü]',c:'[cç]'}[c]));
let ignores = 0;
const out = [];
for (const r of rows.slice(0, MAX)) {
  if (String(r.dept || '') === '54') { ignores++; continue; } // 54 reserve a Studio Celeste
  let nom = r.nom_commercial;
  if (!nom) { const m = /\(([^)]+)\)/.exec(r.nom || ''); nom = m ? m[1] : (r.nom || ''); }
  const jetons = slug(nom).split(' ').filter(t => t.length >= 2 && !STOP.has(t));
  const longest = [...jetons].sort((a, b) => b.length - a.length)[0] || '';
  const ville = slug(r.ville).replace(/ /g, '[ -]');
  const q = '[out:json][timeout:25];\n' +
    'area["name"~"^' + accent(ville) + '$",i]["boundary"="administrative"]->.a;\n' +
    'nwr(area.a)["name"~"' + accent(longest) + '",i];\nout tags center 20;';
  out.push({ json: { siren: String(r.siren || ''), cle: r.cle || '', nom: r.nom || '', nom_recherche: nom, jetons, ville: r.ville || '',
    dept: String(r.dept || ''), overpass_query: longest.length >= 3 ? q : '', web_query: '"' + nom + '" ' + (r.ville || ''), ignores_54: ignores } });
}
if (!out.length) return [{ json: { siren: '', overpass_query: '', web_query: '', vide: true, ignores_54: ignores } }];
return out;

// Assemble l'enrichissement. Regle : une etiquette presente est une preuve, une absence n'en est pas une.
// Jamais de gbp_absente / reseaux_inactifs / pas_de_site=true produits ici.
const rows = $('Preparer les requetes').all().map(i => i.json);
const osmAll = $('Overpass OSM').all().map(i => i.json);
const webAll = $('Recherche web').all().map(i => i.json);
const today = new Date().toISOString().slice(0, 10);
const slug = s => (s || '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const EXCLUS = ['facebook.','instagram.','linkedin.','twitter.','x.com','tiktok.','youtube.','pappers.','societe.com','infogreffe.','pagesjaunes.','annuaire','verif.com','manageo.','bodacc','data.gouv','entreprises.gouv','gouv.fr','lefigaro','tripadvisor','yelp.','mappy.','google.','bing.','duckduckgo.','wikipedia.','indeed.','leboncoin.','planity.','doctolib.','ubereats.','justeat.','travauxbat','118218','cylex','kompass','europages','hoodspot','score3','lespagesjaunes','mon-artisan','starofservice','habitissimo','malt.','fr.linkedin','trustpilot','allobiz','entreprises.lefigaro','petitfute','bottin','journaldunet','dirigeant','rubypayeur','northdata','ellisphere','ouvert','horaires'];
const lines = [];
let osmOk = 0, webOk = 0, webBloque = 0;
rows.forEach((p, idx) => {
  if (p.vide || !p.siren) return;
  let osm = osmAll[idx] || {};
  let osmTxt = '';
  if (typeof osm.data === 'string') { osmTxt = osm.data; try { osm = JSON.parse(osm.data); } catch (e) { osm = { error: 'reponse_non_json' }; } }
  const web = webAll[idx] || {};
  const diag = {};
  const ev = { signaux: {} };
  const src = [];
  // --- OSM ---
  if (!p.overpass_query) diag.osm = 'non_interroge';
  else if (osm.error || !Array.isArray(osm.elements)) diag.osm = 'echec_requete : ' + ((osm.error && osm.error.message) || osm.error || '') + ' ' + osmTxt.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 160);
  else {
    osmOk++;
    const need = p.jetons.length;
    const match = osm.elements.filter(e => {
      const n = slug((e.tags || {}).name);
      const hit = p.jetons.filter(t => n.split(' ').includes(t)).length;
      return need > 0 && hit / need >= 0.8 && p.jetons.some(t => t.length >= 4 && n.split(' ').includes(t));
    });
    if (!match.length) diag.osm = 'aucun_objet_correspondant (ne prouve rien)';
    else {
      const t = match[0].tags;
      diag.osm = 'trouve ' + match[0].type + '/' + match[0].id;
      const site = t.website || t['contact:website'] || t.url;
      const tel = t.phone || t['contact:phone'] || t['contact:mobile'];
      if (site) { ev.site = site; ev.signaux.pas_de_site = false; src.push('OSM ' + match[0].type + '/' + match[0].id + ' tag website (overpass-api.de, ' + today + ')'); }
      if (tel) { ev.telephone = tel; src.push('OSM ' + match[0].type + '/' + match[0].id + ' tag phone (overpass-api.de, ' + today + ')'); }
    }
  }
  // --- Recherche web ---
  const html = typeof web === 'string' ? web : (web.data || web.body || '');
  if (!p.web_query) diag.web = 'non_interroge';
  else if (web.error) diag.web = 'echec_requete';
  else if (!/result__a/.test(html)) { diag.web = 'bloque_ou_vide : ' + html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 120); webBloque++; }
  else {
    webOk++;
    const cands = [];
    const parts = html.split('class="result__a"').slice(1, 11);
    for (const part of parts) {
      const hm = /href="([^"]+)"/.exec(part); if (!hm) continue;
      let href = hm[1].replace(/&amp;/g, '&');
      const u = /uddg=([^&]+)/.exec(href); if (u) href = decodeURIComponent(u[1]);
      let host; try { host = new URL(href.startsWith('//') ? 'https:' + href : href).hostname.replace(/^www\./, ''); } catch (e) { continue; }
      cands.push({ url: href, host, texte: slug(part.slice(0, 2500).replace(/<[^>]+>/g, ' ')) });
    }
    const villeSlug = slug(p.ville);
    const ok = cands.filter(c => !EXCLUS.some(x => c.host.includes(x)) &&
      p.jetons.some(t => t.length >= 4 && slug(c.host).replace(/ /g, '').includes(t)) && c.texte.includes(villeSlug));
    diag.web = ok.length ? 'site_officiel_probable ' + ok[0].host : 'aucun_candidat_fiable (' + cands.length + ' resultats ecartes)';
    if (ok.length && !ev.site) {
      ev.site = ok[0].url; ev.signaux.pas_de_site = false;
      src.push('recherche web duckduckgo ' + today + ' : domaine ' + ok[0].host + ' (nom + ville dans le resultat)');
    }
    if (!ok.length && cands.length) diag.web_candidats_non_retenus = cands.slice(0, 3).map(c => c.host);
  }
  const rec = { siren: p.siren, cle: p.cle || ('siren:' + p.siren), verif_sources: diag };
  if (ev.site) rec.site = ev.site;
  if (ev.telephone) rec.telephone = ev.telephone;
  if (Object.keys(ev.signaux).length) rec.signaux = ev.signaux;
  rec.source = src.length ? src.join(' ; ') : 'n8n VPS ' + today + ' : aucune preuve trouvee (osm: ' + diag.osm + ' ; web: ' + diag.web + ')';
  lines.push(JSON.stringify(rec));
});
return [{ json: { count: lines.length, osm_interroge_ok: osmOk, web_ok: webOk, web_bloque: webBloque, ignores_54: rows[0] ? rows[0].ignores_54 : 0, ndjson: lines.join('\n') + (lines.length ? '\n' : '') } }];
